BEGIN;
SET LOCAL statement_timeout='10s';
DO $verify$
DECLARE actor uuid := gen_random_uuid(); grant_at timestamptz := clock_timestamp();
BEGIN
  INSERT INTO auth.users(id) VALUES(actor);
  UPDATE public.feature_flags SET enabled=true WHERE flag='input_outcome_learning_enabled';
  INSERT INTO public.input_outcome_consent(user_id,enabled,consent_version,consented_at)
    VALUES(actor,true,'input_outcome_learning_v1',grant_at);
  SET LOCAL ROLE service_role;
  IF public.input_record_outcome(actor,'city_picker','city','ci-synthetic',grant_at) IS DISTINCT FROM true
     OR public.input_record_task_outcome(actor,grant_at,'city_picker','trip_created',true) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'current service grant was not admitted';
  END IF;
  IF public.input_record_outcome(actor,'city_picker','city','ci-synthetic') IS DISTINCT FROM false
     OR public.input_record_task_outcome('city_picker','trip_created',true) IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'legacy writer remained active';
  END IF;
  UPDATE public.input_outcome_consent SET enabled=false,withdrawn_at=now() WHERE user_id=actor;
  DELETE FROM public.input_outcome_counters WHERE user_id=actor;
  IF public.input_record_outcome(actor,'city_picker','city','ci-synthetic',grant_at) IS DISTINCT FROM false
     OR public.input_record_task_outcome(actor,grant_at,'city_picker','trip_created',true) IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'withdrawn grant was admitted';
  END IF;
  UPDATE public.input_outcome_consent SET enabled=true,withdrawn_at=null,consented_at=grant_at+interval '1 second' WHERE user_id=actor;
  IF public.input_record_outcome(actor,'city_picker','city','ci-synthetic',grant_at) IS DISTINCT FROM false
     OR public.input_record_task_outcome(actor,grant_at,'city_picker','trip_created',true) IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'previous grant was admitted';
  END IF;
  IF EXISTS(SELECT 1 FROM public.input_outcome_counters WHERE user_id=actor) THEN
    RAISE EXCEPTION 'erased counters reappeared';
  END IF;
  IF public.input_record_outcome(actor,'city_picker','city','ci-synthetic',grant_at+interval '1 second') IS DISTINCT FROM true
     OR public.input_record_task_outcome(actor,grant_at+interval '1 second','city_picker','trip_created',true) IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'new current grant was not admitted';
  END IF;
  UPDATE public.feature_flags SET enabled=false WHERE flag='input_outcome_learning_enabled';
  IF public.input_record_outcome(actor,'city_picker','city','ci-synthetic',grant_at+interval '1 second') IS DISTINCT FROM false
     OR public.input_record_task_outcome(actor,grant_at+interval '1 second','city_picker','trip_created',true) IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'disabled feature admitted a write';
  END IF;
  RESET ROLE;
END $verify$;
ROLLBACK;
SELECT '4029 final migration service-role assertions passed; all fixtures and flag changes rolled back' AS result, now() AS verified_at;

BEGIN;
SET LOCAL statement_timeout='10s';
DO $verify$
DECLARE actor uuid:=gen_random_uuid(); grant_at timestamptz:=clock_timestamp();
 rows jsonb:='[{"schema_version":"1.0","payload":{"objectId":"ci-synthetic","objectType":"place","outcome":"see_place"}}]';
BEGIN
 INSERT INTO auth.users(id) VALUES(actor);
 INSERT INTO public.profiles(id,handle,name) VALUES(actor,'ciw_'||replace(actor::text,'-',''),'CI signal verification');
 INSERT INTO public.intel_contribution_consent(user_id,enabled,consent_version,consented_at)
 VALUES(actor,true,'intel_contributions_v1',grant_at);
 SET LOCAL ROLE service_role;
 IF public.insert_wall_telemetry_outcomes(actor,rows,NULL)<>0 THEN RAISE EXCEPTION 'missing grant admitted'; END IF;
 IF public.insert_wall_telemetry_outcomes(actor,rows,grant_at)<>1 THEN RAISE EXCEPTION 'current grant refused'; END IF;
 UPDATE public.intel_contribution_consent SET enabled=false,withdrawn_at=now() WHERE user_id=actor;
 IF public.insert_wall_telemetry_outcomes(actor,rows,grant_at)<>0 THEN RAISE EXCEPTION 'withdrawal admitted'; END IF;
 UPDATE public.intel_contribution_consent SET enabled=true,withdrawn_at=null,consented_at=grant_at+interval '1 second' WHERE user_id=actor;
 IF public.insert_wall_telemetry_outcomes(actor,rows,grant_at)<>0 THEN RAISE EXCEPTION 'stale grant admitted'; END IF;
 IF public.insert_wall_telemetry_outcomes(actor,rows,grant_at+interval '1 second')<>1 THEN RAISE EXCEPTION 'new grant refused'; END IF;
 INSERT INTO public.wall_telemetry_events(viewer_id,event_name,payload) VALUES(actor,'wall_real_world_outcome','{}');
 IF (SELECT count(*) FROM public.wall_telemetry_events WHERE viewer_id=actor)<>2 THEN RAISE EXCEPTION 'legacy direct insert admitted'; END IF;
 INSERT INTO public.wall_telemetry_events(viewer_id,event_name,payload) VALUES(actor,'wall_feed_open','{"mode":"for_you"}');
 IF (SELECT count(*) FROM public.wall_telemetry_events WHERE viewer_id=actor)<>3 THEN RAISE EXCEPTION 'ordinary event changed'; END IF;
 RESET ROLE;
 IF has_function_privilege('anon','public.insert_wall_telemetry_outcomes(uuid,jsonb,timestamptz)','EXECUTE')
 OR has_function_privilege('authenticated','public.insert_wall_telemetry_outcomes(uuid,jsonb,timestamptz)','EXECUTE') THEN RAISE EXCEPTION 'client authority expanded'; END IF;
END $verify$;
ROLLBACK;
SELECT '4030 final migration service-role grant/refusal and ordinary-event assertions passed; fixture rolled back' AS result,now() AS verified_at;

BEGIN;
SET LOCAL statement_timeout='20s';
DO $verify$
DECLARE actor uuid:=gen_random_uuid(); viewer uuid:=gen_random_uuid(); post uuid:=gen_random_uuid();
 composer_id uuid:=gen_random_uuid(); reject_id uuid:=gen_random_uuid(); n integer; receipt jsonb; rows jsonb;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor),(viewer);
 INSERT INTO public.profiles(id,handle,name) VALUES(actor,'cim_'||replace(actor::text,'-',''),'CI signal verification'),(viewer,'cim_'||replace(viewer::text,'-',''),'CI signal verification');
 INSERT INTO public.posts(id,author_id,created_by,visibility,post_status,add_to_passport) VALUES(post,actor,actor,'private','draft',false);
 rows:=jsonb_build_array(jsonb_build_object('id',composer_id,'event_type','composer_outcome','payload',jsonb_build_object('version',1,'surface','post','outcome','published')));
 SET LOCAL ROLE service_role;
 IF public.admit_composer_outcomes(actor,rows) IS DISTINCT FROM true OR public.admit_composer_outcomes(actor,rows) IS DISTINCT FROM true THEN RAISE EXCEPTION 'valid idempotent composer admission failed'; END IF;
 IF (SELECT count(*) FROM public.media_events WHERE id=composer_id)<>1 THEN RAISE EXCEPTION 'duplicate composer outcome'; END IF;
 BEGIN
  PERFORM public.admit_composer_outcomes(actor,jsonb_build_array(jsonb_build_object('id',composer_id,'event_type','composer_outcome','payload',jsonb_build_object('version',1,'surface','post','outcome','discarded_draft'))));
  RAISE EXCEPTION 'conflicting duplicate accepted';
 EXCEPTION WHEN raise_exception THEN
  IF SQLERRM<>'composer_admission_conflict' THEN RAISE; END IF;
 END;
 INSERT INTO public.media_events(event_type,payload) VALUES('impression',jsonb_build_object('viewer_id',actor)),('impression',jsonb_build_object('viewer_id',viewer,'creator_id',actor)),('impression',jsonb_build_object('viewer_id',viewer,'media_id',post));
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>3 THEN RAISE EXCEPTION 'valid media events refused'; END IF;
 INSERT INTO public.media_events(id,event_type,payload) VALUES(reject_id,'impression',jsonb_build_object('viewer_id',actor,'text','synthetic forbidden input'));
 IF EXISTS(SELECT 1 FROM public.media_events WHERE id=reject_id) THEN RAISE EXCEPTION 'unexpected payload accepted'; END IF;
 receipt:=public.erase_media_events_for_actor(actor,2);
 IF receipt IS DISTINCT FROM '{"deleted":2,"more":true}'::jsonb THEN RAISE EXCEPTION 'first bounded erase receipt unexpected'; END IF;
 receipt:=public.erase_media_events_for_actor(actor,2);
 IF receipt IS DISTINCT FROM '{"deleted":1,"more":false}'::jsonb THEN RAISE EXCEPTION 'final erase receipt unexpected'; END IF;
 IF public.erase_media_events_for_actor(actor,2) IS DISTINCT FROM '{"deleted":0,"more":false}'::jsonb THEN RAISE EXCEPTION 'erase retry not idempotent'; END IF;
 IF public.admit_composer_outcomes(actor,rows) IS DISTINCT FROM false THEN RAISE EXCEPTION 'fenced actor composer admission succeeded'; END IF;
 INSERT INTO public.media_events(id,event_type,payload) VALUES(reject_id,'impression',jsonb_build_object('viewer_id',viewer,'media_id',post));
 IF EXISTS(SELECT 1 FROM public.media_events WHERE id=reject_id) THEN RAISE EXCEPTION 'fenced creator reference admitted'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.media_events WHERE id=composer_id AND NOT(payload ? 'viewer_id')) THEN RAISE EXCEPTION 'unlinked historical composer treatment changed'; END IF;
 IF public.purge_expired_media_events(1) IS DISTINCT FROM '{"enabled":false,"deleted":0,"more":false}'::jsonb THEN RAISE EXCEPTION 'unapproved retention activated'; END IF;
 RESET ROLE;
 IF has_function_privilege('authenticated','public.erase_media_events_for_actor(uuid,integer)','EXECUTE')
 OR has_function_privilege('anon','public.admit_composer_outcomes(uuid,jsonb)','EXECUTE')
 OR has_table_privilege('authenticated','public.media_event_erasure_fences','SELECT') THEN RAISE EXCEPTION 'client authority expanded'; END IF;
END $verify$;
ROLLBACK;
SELECT '4031 service-role admission, idempotency, erasure, payload, retention hold and access assertions passed; all fixtures rolled back' AS result,now() AS verified_at;

BEGIN;
SET LOCAL statement_timeout='10s';
DO $verify$
DECLARE actor uuid:=gen_random_uuid(); grant_at timestamptz:=clock_timestamp(); receipt jsonb;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor);
 UPDATE public.feature_flags SET enabled=true WHERE flag='input_outcome_learning_enabled';
 INSERT INTO public.input_outcome_consent(user_id,enabled,consent_version,consented_at) VALUES(actor,true,'input_outcome_learning_v1',grant_at);
 INSERT INTO public.input_outcome_counters(user_id,context,entity_type,entity_id) VALUES(actor,'city_picker','city','ci-synthetic');
 SET LOCAL ROLE service_role;
 receipt:=public.input_outcome_memory(actor,'city_picker',current_date-29);
 IF receipt->'active' IS DISTINCT FROM 'true'::jsonb OR jsonb_array_length(receipt->'counts')<>1 THEN RAISE EXCEPTION 'current grant read failed'; END IF;
 UPDATE public.input_outcome_consent SET consent_version='old_disclosure' WHERE user_id=actor;
 IF public.input_outcome_memory(actor,'city_picker',current_date-29) IS DISTINCT FROM '{"active":false}'::jsonb THEN RAISE EXCEPTION 'old disclosure influenced memory'; END IF;
 UPDATE public.input_outcome_consent SET consent_version='input_outcome_learning_v1',enabled=false,withdrawn_at=now() WHERE user_id=actor;
 IF public.input_outcome_memory(actor,'city_picker',current_date-29) IS DISTINCT FROM '{"active":false}'::jsonb THEN RAISE EXCEPTION 'withdrawn memory read succeeded'; END IF;
 RESET ROLE;
 IF has_function_privilege('anon','public.input_outcome_memory(uuid,text,date)','EXECUTE') OR has_function_privilege('authenticated','public.input_outcome_memory(uuid,text,date)','EXECUTE') OR (SELECT prosecdef FROM pg_proc WHERE oid='public.input_outcome_memory(uuid,text,date)'::regprocedure) THEN RAISE EXCEPTION 'reader authority mismatch'; END IF;
END $verify$;
ROLLBACK;
SELECT '4032 current-disclosure, withdrawal and service-only reader assertions passed; fixtures and flags rolled back' AS result,now() AS verified_at;
